import { z } from "zod";
const zIFrameProps = z.object({
    src: z.string(),
    size: z.enum(["s", "m", "l", "stretch"]).default("m"),
    width: z.number().int().positive().optional(),
    height: z.number().int().positive().optional(),
    title: z.string().optional(),
    sandbox: z.string().optional(),
    allow: z.string().optional(),
    fullscreen: z.boolean().optional(),
});
export function IFrameWidget(define) {
    return define("IFrame")
        .props(zIFrameProps)
        .render((props) => ({
        src: props.src,
        size: props.size,
        width: props.width,
        height: props.height,
        title: props.title,
        allow: props.allow,
        sandbox: props.sandbox,
        fullscreen: props.fullscreen,
    }));
}
